          if (lab) lab.classList.add('v3-flash');
          try{ const nm = String((state.players[i] && (state.players[i].name || state.players[i].player)) || '').split(' ')[0]; __sqV3DisplayEvent((nm || 'PLAYER') + ' WINS!', true, 'WINNER', 3200); }catch(_){ }
