// League Low Scores — Admin dialog
async function openLeagueLowsAdminDialog(){
  const overlay = document.createElement('div'); overlay.className='modal-backdrop';
  const modal   = document.createElement('div'); modal.className='modal';
  const title   = document.createElement('h3');  title.textContent='League Low Scores — Admin';
  const body    = document.createElement('div'); body.className='modal-body';
  const footer  = document.createElement('div'); footer.className='modal-footer';

  async function render(){
    body.innerHTML = '';

    try{
      if (typeof ensureCloudInit === 'function' && !ensureCloudInit()){
        const p = document.createElement('p');
        p.textContent = 'Cloud not initialised.';
        body.appendChild(p);
        return;
      }
    }catch(_){}

      // >>> PATCH:MOT3_2_LLS_FILTER_SAVED START
  let __llsSavedSet = null;
  try{
    const __ps = await (typeof cloudListPlayers === 'function' ? cloudListPlayers() : []);
    __llsSavedSet = new Set((__ps||[]).map(p=>String(p?.name||'').trim().toLowerCase()).filter(Boolean));
  }catch(_){ __llsSavedSet = null; }
  // <<< PATCH:MOT3_2_LLS_FILTER_SAVED END

// Derived low scores from official games (no dedicated table required)
    let rows = [];
    try{
      const games = await cloudFetchAllGamesAsLocal();
      (games||[]).filter(isOfficialGame).forEach(g=>{
        const ts = g.ts || g.created_at || g.inserted_at || (g.meta && (g.meta.ts || g.meta.date)) || null;
        const players = Array.isArray(g.players) ? g.players : [];
        const totals  = Array.isArray(g.totals)  ? g.totals  : [];
        players.forEach((p,i)=>{
          const name = (typeof p==='string') ? p : (p && p.name) ? p.name : '';
          if (!name) return;
          const __k = String(name).trim().toLowerCase();
          const __savedSet = (typeof __llsSavedSet !== "undefined" ? __llsSavedSet : (window.__llsSavedSet || null));
          if (__savedSet && !__savedSet.has(__k)) return;
          rows.push({ name, score: Number(totals[i]||0), ts, __game: g });
        });
      });
      rows.sort((a,b)=> (a.score-b.score) || (Date.parse(a.ts||'')-Date.parse(b.ts||'')));
      rows = rows.slice(0, 50);
    }catch(e){
      console.error('League low scores derived fetch failed', e);
      const p = document.createElement('p');
      p.textContent = 'Failed to load league low scores.';
      body.appendChild(p);
      return;
    }

    if (!rows.length){
      const p = document.createElement('p');
      p.textContent = 'No league low scores found.';
      body.appendChild(p);
      return;
    }

    const table = document.createElement('table'); table.className='hs-table compact';
    const thead = document.createElement('thead'); const trh=document.createElement('tr');
    ['#','Player','Score','When','Actions'].forEach(h=>{
      const th=document.createElement('th'); th.textContent=h; trh.appendChild(th);
    });
    thead.appendChild(trh); table.appendChild(thead);

    const tb = document.createElement('tbody');

    rows.forEach((row, idx) => {
      const tr = document.createElement('tr');

      const td1 = document.createElement('td'); td1.textContent = String(idx+1);
      const td2 = document.createElement('td'); td2.textContent = row.name || '';
      const td3 = document.createElement('td'); td3.textContent = String(row.score ?? '');

      const td4 = document.createElement('td');
      const d   = new Date(row.ts);
      td4.textContent = !Number.isNaN(d.getTime())
        ? d.toLocaleString(undefined,{year:'2-digit',month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'})
        : '';
      td4.style.fontSize = '0.8rem';

      const td5 = document.createElement('td'); td5.className='center';
      const del = document.createElement('button'); del.className='btn small danger'; del.textContent='Delete';
      del.onclick = async (e) => {
        e.stopPropagation();
        if (!confirm(`Delete ${row.name}'s low score of ${row.score}?`)) return;
        try{
          // Derived list: delete the underlying game instead
          if (!row.__game) throw new Error('Missing game for delete');
          await cloudDeleteGameCascade(Object.assign({}, row.__game, { ts: row.ts }));// >>> PATCH:MOT3_2_LLS_DELETE_TS

          if (typeof toast === 'function') toast('Deleted');
          await render();
        }catch(err){
          console.error('Delete league low score failed', err);
          if (typeof toast === 'function') toast('Delete failed');
        }
      };
      td5.appendChild(del);

      tr.append(td1, td2, td3, td4, td5);
      tb.appendChild(tr);
    });

    table.appendChild(tb);
    body.appendChild(table);
  }

  await render();

  const backBtn  = document.createElement('button'); backBtn.className='btn'; backBtn.textContent='Back';
  backBtn.onclick = ()=>{ overlay.remove(); if (typeof openAdminHub === 'function') openAdminHub(); };
  const closeBtn = document.createElement('button'); closeBtn.className='btn'; closeBtn.textContent='Exit';
  closeBtn.onclick = ()=> overlay.remove();
  footer.append(backBtn, closeBtn);

  modal.append(title, body, footer);
  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  overlay.addEventListener('click', e=>{ if(e.target===overlay) overlay.remove(); });
  overlay.addEventListener('keydown', e=>{ if(e.key==='Escape') overlay.remove(); });
  modal.tabIndex=0; modal.focus();
}

// All Games dialog (cloud-only, with Delete and re-render)
async function openAllGamesDialog(){
  const overlay = document.createElement('div'); overlay.className='modal-backdrop';
  const modal   = document.createElement('div'); modal.className='modal';
  const title   = document.createElement('h3');  title.textContent='All Games';
  const body    = document.createElement('div'); body.className='modal-body';
  const footer  = document.createElement('div'); footer.className='modal-footer';

  // >>> PATCH:MOT3_2_ALLGAMES_TOTS START
  const toTS = (g)=>{
    const t = g?.ts || g?.created_at || g?.inserted_at || (g?.meta && (g.meta.ts || g.meta.date)) || null;
    const n = t ? Date.parse(t) : NaN;
    return Number.isFinite(n) ? n : 0;
  };
  // <<< PATCH:MOT3_2_ALLGAMES_TOTS END

  // Header with filter controls (top-right)
  const header = document.createElement('div');
  header.style.cssText = 'display:flex; align-items:center; justify-content:space-between; gap:8px;';
  const controls = document.createElement('div');
  controls.style.cssText = 'display:flex; gap:6px;';
  const officialBtn = document.createElement('button'); officialBtn.className='btn primary'; officialBtn.textContent='Official';
  const turboBtn = document.createElement('button'); turboBtn.className='btn';             turboBtn.textContent='Turbo';
  const practiceBtn = document.createElement('button'); practiceBtn.className='btn';          practiceBtn.textContent='Practice';
  const archivedBtn = document.createElement('button'); archivedBtn.className='btn';         archivedBtn.textContent='Archived';
  controls.append(officialBtn, turboBtn, practiceBtn, archivedBtn);
  header.append(title, controls);

  // Filter state + saved players cache
  let filterMode = 'official';
  let savedSet = null;
  async function getSavedSet(){
    try{
      if (savedSet) return savedSet;
      const players = await (typeof cloudListPlayers === 'function' ? cloudListPlayers() : []);
      savedSet = new Set((players||[]).map(p => String(p?.name || '').trim().toLowerCase()).filter(Boolean));
      return savedSet;
    }catch(_){
      savedSet = new Set();
      return savedSet;
    }
  }

  // Wire filter buttons
  officialBtn.onclick = async ()=>{
    filterMode = 'official';
    officialBtn.className = 'btn primary';
    turboBtn.className = 'btn';
    practiceBtn.className = 'btn';
    archivedBtn.className = 'btn';
    await render();
  };
  turboBtn.onclick = async ()=>{
    filterMode = 'turbo';
    turboBtn.className = 'btn primary';
    officialBtn.className = 'btn';
    practiceBtn.className = 'btn';
    archivedBtn.className = 'btn';
    await render();
  };

  practiceBtn.onclick = async ()=>{
    filterMode = 'practice';
    practiceBtn.className = 'btn primary';
    officialBtn.className = 'btn';
    turboBtn.className = 'btn';
    archivedBtn.className = 'btn';
    await render();
  };
  archivedBtn.onclick = async ()=>{
    filterMode = 'archived';
    archivedBtn.className = 'btn primary';
    officialBtn.className = 'btn';
    turboBtn.className = 'btn';
    practiceBtn.className = 'btn';
    await render();
  };

  async function render(){
    body.innerHTML = '';

    // Build list (cloud games only; no synthetic backfill here to avoid duplicates)
    let cloudGames = [];
    try { cloudGames = await cloudFetchAllGamesAsLocal(); } catch(e){ console.error(e); cloudGames = []; }

    // >>> PATCH:MOT3_3_ALLGAMES_FILTER_ACTIVE_START
    const saved = await getSavedSet();

    const norm = (s)=>String(s||'').trim().toLowerCase();
    const playerNames = (g)=> (Array.isArray(g?.players)? g.players: []).map(p=>{
      if (typeof p === 'string') return p;
      return (p && p.name) ? p.name : '';
    }).filter(Boolean);

    const hasAnySavedPlayer = (g)=>{
      if (!saved || !saved.size) return false;
      return playerNames(g).some(nm => saved.has(norm(nm)));
    };

    const isExplicitPractice = (g)=>{
      return (g?.mode === 'practice' || g?.is_practice === true || g?.isPractice === true);
    };

    const isTurboAdmin = (g)=>{
      const st = g?.state || {};
      const m = g?.match || st?.match || {};
      const rules = g?.tournamentRules || st?.tournamentRules || m?.tournamentRules || {};
      return String(g?.tournamentType || st?.tournamentType || m?.tournamentType || '').toLowerCase() === 'turbo'
        || rules.strictTimer === true
        || Number(rules.throwLimitSeconds || 0) === 20
        || String(rules.startTarget || '').toLowerCase() === '17';
    };

    const isSinglePlayer = (g)=>{
      const pls = playerNames(g);
      return pls.length < 2;
    };

    // OFFICIAL:
    // - NOT practice
    // - 2+ players
    // - at least ONE saved player (allows mixes with guests)
    const isOfficialAdmin = (g)=>{
      if (!g) return false;
      if (isTurboAdmin(g)) return false;
      if (isExplicitPractice(g)) return false;
      if (isSinglePlayer(g)) return false;
      return hasAnySavedPlayer(g);
    };

    let gamesAll = (cloudGames || []).filter(Boolean).sort((a,b)=> toTS(b) - toTS(a));

    // Archived handling: archived games must be invisible in Official/Practice lists,
    // but viewable under the Admin "Archived" tab.
    const isArchivedGame = (g)=> !!(g && (g.archived_at || g.archivedAt));
    const gamesActive = gamesAll.filter(g => !isArchivedGame(g));
    const gamesArchived = gamesAll.filter(g => isArchivedGame(g));
    // PRACTICE:
    // - ALL explicit practice games (solo or multi)
    // - ALL single-player games (treated as practice bucket)
    // - multiplayer non-practice games where nobody is saved (guest-only / unregistered)
    const isPracticeAdmin = (g)=>{
      if (!g) return false;
      if (isTurboAdmin(g)) return false;
      if (isExplicitPractice(g)) return true;
      if (isSinglePlayer(g)) return true;
      // non-practice multiplayer: include only if nobody is saved
      return !hasAnySavedPlayer(g);
    };

    let games = [];
    if (filterMode === 'archived') {
      games = gamesArchived;
    } else if (filterMode === 'turbo') {
      games = gamesActive.filter(g => isTurboAdmin(g));
    } else {
      games = gamesActive.filter(g => {
        return (filterMode === 'official') ? isOfficialAdmin(g) : isPracticeAdmin(g);
      });
    }

    // If there are no saved players available, official should show none (avoid leaking guest-only games into official).
    if (filterMode === 'official' && (!saved || !saved.size)) {
      const p=document.createElement('p');
      p.textContent='No saved players found. Official games require at least one saved player.';
      body.appendChild(p);
      return;
    }

    // IMPORTANT: Do NOT synthesize "practice" games from any high_scores tables.
    // Those tables are per-player score records and can legitimately contain scores from official matches.
    // Practice tab must reflect actual games only (TABLE_GAMES):
    //   - explicit practice games, OR
    //   - multiplayer games with no saved/registered players.
// <<< PATCH:MOT3_3_ALLGAMES_FILTER_ACTIVE_END

    if (!games.length){
      const p=document.createElement('p'); p.textContent='No games found.'; body.appendChild(p); return;
    }

    const table=document.createElement('table'); table.className='hs-table';

    // Column layout: # | When | Players | Totals | Actions
    const colgroup = document.createElement('colgroup');
    const cIdx = document.createElement('col'); cIdx.style.width = '3ch'; colgroup.appendChild(cIdx); // #
    colgroup.appendChild(document.createElement('col')); // When
    colgroup.appendChild(document.createElement('col')); // Players
    colgroup.appendChild(document.createElement('col')); // Totals
    const cAct = document.createElement('col'); cAct.style.width = '88px'; colgroup.appendChild(cAct); // Actions
    table.appendChild(colgroup);

    const thead=document.createElement('thead'); const trh=document.createElement('tr');
    ['#','When','Players','Totals',''].forEach((h,i)=>{
      const th=document.createElement('th'); th.textContent=h;
      if(i===0) th.style.width='3ch';   // # column
      if(i===4) th.style.width=(filterMode==='archived' ? '190px' : '110px');  // actions column
      trh.appendChild(th);
    });
    thead.appendChild(trh); table.appendChild(thead);

    const tb=document.createElement('tbody');
    games.forEach((g, idx)=>{
      const tr=document.createElement('tr');

      const td1=document.createElement('td'); td1.textContent=String(idx+1); td1.style.width='3ch';
      const td2 = document.createElement('td');
      const tsVal = g.ts || g.created_at || g.inserted_at || (g.meta && (g.meta.ts || g.meta.date)) || null;
      td2.textContent = (window.fmtWhen && tsVal) ? window.fmtWhen(tsVal) : '';
      const td3=document.createElement('td'); td3.textContent=(g.players||[]).map(p=> (typeof p==='string'?p:(p&&p.name)||'')).filter(Boolean).join(', ');
      const td4=document.createElement('td'); td4.textContent=(g.totals||[]).join(' · ');

      // Action buttons (Archive / Reinstate / Delete)
      const tdDel=document.createElement('td'); tdDel.className='center'; tdDel.style.display='flex'; tdDel.style.justifyContent='center'; tdDel.style.gap='10px'; tdDel.style.whiteSpace='nowrap';

      if (filterMode === 'archived') {
        const reinBtn=document.createElement('button'); reinBtn.className='btn small'; reinBtn.textContent='Reinstate';
        reinBtn.title='Reinstate this archived game (make visible again everywhere)';
        reinBtn.onclick = async (e)=>{
          e.stopPropagation();
          if (!confirm('Reinstate this archived game?')) return;
          try { await cloudReinstateGame(g); toast('Reinstated'); await render(); }
          catch(err){ console.error(err); toast('Reinstate failed'); }
        };

        const delBtn=document.createElement('button'); delBtn.className='btn small danger'; delBtn.textContent='Delete';
        delBtn.title='PERMANENTLY delete this game and all related data';
        delBtn.onclick = async (e)=>{
          e.stopPropagation();
          const msg = `PERMANENT DELETE

This removes the game and related data everywhere (including high scores).

Type DELETE to confirm:`;
          const typed = prompt(msg);
          if ((typed || '').trim().toUpperCase() !== 'DELETE') return;
          try { await cloudPurgeGameCascade(g); toast('Deleted'); await render(); }
          catch(err){ console.error(err); toast('Delete failed'); }
        };

        tdDel.appendChild(reinBtn);
        tdDel.appendChild(document.createTextNode(' '));
        tdDel.appendChild(delBtn);
      } else {
        const archBtn=document.createElement('button'); archBtn.className='btn small danger'; archBtn.textContent='Archive';
        archBtn.title='Archive this game (remove from all user-visible stats and lists)';
        archBtn.onclick = async (e)=>{
          e.stopPropagation();
          if (!confirm('Archive this game? (It will disappear from stats/high scores everywhere)')) return;
          try { await cloudArchiveGame(g); toast('Archived'); await render(); }
          catch(err){ console.error(err); toast('Archive failed'); }
        };
        tdDel.appendChild(archBtn);
      }

      tr.style.cursor='pointer';
      tr.title='Open score sheet';
      tr.onclick=()=>{ if (typeof openSingleGameScoreSheet === 'function') openSingleGameScoreSheet(g); };

      tr.append(td1, td2, td3, td4, tdDel); tb.appendChild(tr);
    });

    table.appendChild(tb); body.appendChild(table);
  }

  // Footer
  const backBtn=document.createElement('button'); backBtn.className='btn sq-pill'; backBtn.textContent='Back';
  backBtn.onclick=()=>{ overlay.remove(); if (typeof openAdminHub==='function') openAdminHub(); };
  const closeBtn=document.createElement('button'); closeBtn.className='btn sq-pill'; closeBtn.textContent='Close';
  closeBtn.onclick=()=> overlay.remove();
  footer.append(backBtn, closeBtn);

  modal.append(header, body, footer); overlay.appendChild(modal); document.body.appendChild(overlay);
  overlay.addEventListener('click', e=>{ if(e.target===overlay) overlay.remove(); });
  overlay.addEventListener('keydown', e=>{ if(e.key==='Escape') overlay.remove(); });
  modal.tabIndex=0; modal.focus();

  await render();
}

// LEGACY ROUND HIGH SCORES DYNAMIC IMPLEMENTATION — QUARANTINED
// Superseded by v82, v85, and final Fix97/Fix102 path.
// Do not patch this block for current UI unless caller tracing proves it is active.
// [removed: openRoundHighScoresDialog base def (self-quarantined)] audit P5.3 batch 3 — shadowed by later canonical definition
// Delete a game (by timestamp) and its related high-score rows from Supabase
async function cloudDeleteGameCascade(g){
  if (!ensureCloudInit()) throw new Error('Cloud not initialised');

  const gameId = g?.id || g?.game_id || null;
  const ts = g?.ts || g?.created_at || null;
  if (!gameId && !ts) throw new Error('Missing game id/timestamp for delete');

  // 1) Delete the game row (prefer id)
  if (gameId){
    const { error } = await sb.from(TABLE_GAMES).delete().eq('id', gameId);
    if (error) throw error;
  } else {
    // fallback by exact timestamp, then ±2min
    try {
      const { error } = await sb.from(TABLE_GAMES).delete().eq('created_at', ts);
      if (error) throw error;
    } catch (e) {
      const pad = 2 * 60 * 1000;
      const fromIso = new Date(new Date(ts).getTime() - pad).toISOString();
      const toIso   = new Date(new Date(ts).getTime() + pad).toISOString();
      const { error } = await sb.from(TABLE_GAMES).delete().gte('created_at', fromIso).lte('created_at', toIso);
      if (error) throw error;
    }
  }

  // 2) Delete related HS rows (prefer game_id). If schema lacks game_id, fall back to legacy delete.
  const isSingle = (g?.players || []).length === 1;
  const table = isSingle ? TABLE_HS_PRACTICE : TABLE_HS_LEAGUE;

  if (gameId){
    try{
      const { error } = await sb.from(table).delete().eq('game_id', gameId);
      if (error) throw error;
      return;
    }catch(e){
      const msg  = String(e?.message || '');
      const code = String(e?.code || '');
      const missingCol = (code === '42703') || /game_id/i.test(msg);
      if (!missingCol) throw e;
      // else fall through to legacy matching
    }
  }

  const players = g?.players || [];
  const totals  = g?.totals  || [];
  const tasks = players.map((p,i)=>{
    const row = { name: p?.name || '', score: Number(totals[i]||0), ts: ts };
    return cloudDeleteHighScore(row, isSingle).catch(()=>{});
  });
  await Promise.all(tasks);
}

  /*****************
   * CLOUD INIT HELPER
   *****************/
  // ===== @SEC:JS:CLOUD =====
// ===== @JS:CLOUD:SUPABASE_INIT =====
function ensureCloudInit(){
    try {
      // NOTE: file:// is not recommended, but we allow Supabase init attempts for legacy behaviour.
// If the browser blocks it (CORS), we’ll mark cloud offline and continue using local cache where possible.

      // Library present?
      if (typeof window.supabase !== 'object' || !window.supabase.createClient) {
        try { setCloudStatus && setCloudStatus('error', 'Cloud not initialised'); } catch(_) {}
        return false;
      }
      // Keys present?
      if (typeof SUPABASE_URL === 'undefined' || typeof SUPABASE_ANON === 'undefined' || !SUPABASE_URL || !SUPABASE_ANON) {
        try { setCloudStatus && setCloudStatus('error', 'Cloud keys missing'); } catch(_) {}
        return false;
      }
      if (window.__sqInstallEgressCreateClientHook) window.__sqInstallEgressCreateClientHook();
      // Make client if missing
      if (!window.sb) {
        try {
          window.sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON);
          if (window.__sqInstrumentSupabaseClient) window.sb = window.__sqInstrumentSupabaseClient(window.sb);
          sb = window.sb;
        }
        catch (e) {
          console.error('supabase createClient failed', e);
          try { setCloudStatus && setCloudStatus('error', 'Cloud not initialised'); } catch(_) {}
          return false;
        }
      }
      else if (window.__sqInstrumentSupabaseClient) {
        window.sb = window.__sqInstrumentSupabaseClient(window.sb);
      }
      if (!sb && window.sb) sb = window.sb;
      if (sb !== window.sb) sb = window.sb;
      if (window.__sqInstrumentKnownSupabaseClients) window.__sqInstrumentKnownSupabaseClients();
      return true;
    } catch (e) {
      console.error('ensureCloudInit failed', e);
      try { setCloudStatus && setCloudStatus('error', 'Cloud not initialised'); } catch(_) {}
      return false;
    }

// >>> PATCH:MOT_STAGE5A_CLOUD_CONTRACT_PROBE START
// Stage 5A: Supabase “Truth Mode” hardening — Contract probe + health report (read-only)
//
// Enable debug via ?debug=1 or localStorage.SQ_DEBUG='1' (see Stage 2 SQ_DIAG).
// This patch does NOT change gameplay or writes; it only adds probes + reporting.
//
// Usage (console):
//   sqCloudProbe().then(()=>sqCloudHealth());          // runs contract checks
//   sqCloudHealth();               // prints concise report
//   sqCloudContractStatus();       // returns last status object
//
(function(){
  // Contract definition: required objects the UI relies on (tables + views).
  // Keep this list deterministic; prefer constants if present.
  const T = (k, fallback) => {
    try { return (typeof window[k] !== 'undefined' && window[k]) ? window[k] : fallback; } catch(_){ return fallback; }
  };

  const CONTRACT = [
    { name: T('TABLE_GAMES', 'games'), kind: 'table', usedBy: ['cloudFetch*Games', 'getGamesForMode', 'de-dupe'] },
    { name: T('TABLE_MATCHES', 'matches'), kind: 'table', usedBy: ['cloudFetchAllMatchesAsLocal', 'getMatchesOfficial'] },
    { name: T('TABLE_PLAYER_GAMES', 'player_games_union'), kind: 'view', usedBy: ['player stats windows'] },
    { name: T('TABLE_HS_LEAGUE', 'high_scores_sp'), kind: 'table|view', usedBy: ['High Score League modal'] },
    { name: T('TABLE_HS_PRACTICE', 'high_scores'), kind: 'table', usedBy: ['practice highs'] },
    { name: T('TABLE_PB_ROUNDS_CLEAN_APP', 'v_pb_by_player_round_clean_app'), kind: 'view', usedBy: ['PB rounds / records'] },
    { name: T('TABLE_WR_ROUNDS_CLEAN_APP', 'v_wr_by_round_clean_app'), kind: 'view', usedBy: ['WR rounds / records'] },
    { name: 'v_round_high_scores_modal', kind: 'view', usedBy: ['Round High Scores modal'] },
    { name: 'v_top50_scores_official', kind: 'view', usedBy: ['Top 50 Scores modal'] }
  ];

  // Expose contract list read-only-ish
  window.SQ_CLOUD_CONTRACT = CONTRACT;

  // Internal last-known status
  let _last = null;

  function _isDebug(){
    try {
      if (window.SQ_DIAG && window.SQ_DIAG.enabled) return true;
      const qs = String(location.search || '');
      if (qs.indexOf('debug=1') >= 0) return true;
      if (localStorage && localStorage.getItem('SQ_DEBUG') === '1') return true;
    } catch(_){}
    return false;
  }

  async function _probeOne(obj){
    const started = Date.now();
    const out = {
      name: obj.name,
      kind: obj.kind,
      usedBy: obj.usedBy || [],
      ok: false,
      missing: false,
      rowsUnknown: true,
      error: null,
      ms: 0
    };

    if (!ensureCloudInit()) {
      out.error = 'Cloud not initialised';
      out.ms = Date.now() - started;
      return out;
    }

    // First: cheap HEAD check for existence (works even if no "id" column)
    try {
      const res = await sb.from(obj.name).select('*', { head: true, count: 'exact' }).limit(1);
      if (res && res.error) throw res.error;
      out.ok = true;
      out.missing = false;
      out.rowsUnknown = false;
      // count is null on some configs; treat as unknown rather than lying
      if (typeof res.count === 'number') out.count = res.count;
    } catch (e1) {
      const msg = String(e1 && (e1.message || e1.details || e1.hint) || e1 || '');
      // Supabase/PostgREST common “missing relation/view” signatures
      const missingSig = /relation .* does not exist|Could not find the|404|Not Found|PGRST/i.test(msg);
      out.ok = false;
      out.missing = !!missingSig;
      out.error = msg || 'Probe failed';
      // Mark missing table/view in your existing guardrail map (non-fatal)
      try {
        if (out.missing && typeof cloudMarkTableMissing === 'function') cloudMarkTableMissing(obj.name);
      } catch(_){}
    }

    out.ms = Date.now() - started;
    return out;
  }

  window.sqCloudProbe = async function sqCloudProbe(){
    const started = Date.now();
    const status = {
      at: new Date().toISOString(),
      ok: false,
      cloudInit: false,
      total: CONTRACT.length,
      okCount: 0,
      missingCount: 0,
      failedCount: 0,
      items: [],
      ms: 0
    };

    status.cloudInit = ensureCloudInit();
    if (!status.cloudInit) {
      status.ok = false;
      status.failedCount = CONTRACT.length;
      status.items = CONTRACT.map(o => ({
        name: o.name, kind: o.kind, usedBy: o.usedBy || [],
        ok: false, missing: false, rowsUnknown: true, error: 'Cloud not initialised', ms: 0
      }));
      status.ms = Date.now() - started;
      _last = status;
      if (_isDebug()) console.warn('[SQ CLOUD PROBE] Cloud not initialised');
      return status;
    }

    const results = [];
    for (const obj of CONTRACT) results.push(await _probeOne(obj));

    status.items = results;
    status.okCount = results.filter(r => r.ok).length;
    status.missingCount = results.filter(r => r.missing).length;
    status.failedCount = results.filter(r => !r.ok && !r.missing).length;
    status.ok = (status.okCount === status.total);
    status.ms = Date.now() - started;

    _last = status;

    if (_isDebug()) {
      console.log('[SQ CLOUD PROBE]', status);
      try {
        const rows = results.map(r => ({
          name: r.name,
          kind: r.kind,
          ok: r.ok ? 'OK' : (r.missing ? 'MISSING' : 'FAIL'),
          ms: r.ms,
          error: r.ok ? '' : (r.error || '')
        }));
        console.table(rows);
      } catch(_){}
    }
    return status;
  };

  window.sqCloudContractStatus = function sqCloudContractStatus(){
    return _last;
  };

  window.sqCloudHealth = function sqCloudHealth(){
    const s = _last;
    if (!s) {
      console.log('[SQ CLOUD HEALTH] No probe run yet. Run: sqCloudProbe().then(()=>sqCloudHealth())');
      return { ok:false, msg:'No probe run yet' };
    }
    const msg = s.ok
      ? `OK (${s.okCount}/${s.total})`
      : `NOT OK (ok:${s.okCount}/${s.total}, missing:${s.missingCount}, fail:${s.failedCount})`;
    console.log('[SQ CLOUD HEALTH]', msg, s);
    return { ok: !!s.ok, msg, status: s };
  };

  // Convenience helper for Safari consoles that don't support top-level await
  window.sqCloudProbeNow = function sqCloudProbeNow(){
    try{
      return Promise.resolve(window.sqCloudProbe()).then((r)=>{ try{ window.sqCloudHealth(); }catch(_e){} return r; });
    }catch(e){
      return Promise.reject(e);
    }
  };

})();
// <<< PATCH:MOT_STAGE5A_CLOUD_CONTRACT_PROBE END

  }
// >>> PATCH:MOT5B3_ARCHIVE_REINSTATE_PURGE START
async function cloudArchiveGame(game){
  await ensureCloudInit();
  const gid = (typeof game === 'object' && game) ? (game.id || game.game_id || null) : game;
  if (!gid) throw new Error('cloudArchiveGame: missing game id');
  const { error } = await sb.from(TABLE_GAMES).update({ archived_at: new Date().toISOString() }).eq('id', gid);
  if (error) throw error;
  try{ if (typeof window.__sqClearGamesTruthCache === 'function') window.__sqClearGamesTruthCache('cloudArchiveGame'); }catch(_){ }
  try{ localStorage.removeItem('SQ_PSTICKER_CACHE_V1'); }catch(_){ }
  try{ if (typeof window.__sqRefreshRecentMatchesTicker==='function') window.__sqRefreshRecentMatchesTicker(); }catch(_){ }
  try{ localStorage.removeItem('SQ_PSTICKER_CACHE_V1'); }catch(_){ }
  try{ if (typeof window.__sqRefreshRecentMatchesTicker==='function') window.__sqRefreshRecentMatchesTicker(); }catch(_){ }
  return true;
}

async function cloudReinstateGame(game){
  await ensureCloudInit();
  const gid = (typeof game === 'object' && game) ? (game.id || game.game_id || null) : game;
  if (!gid) throw new Error('cloudReinstateGame: missing game id');
  const { error } = await sb.from(TABLE_GAMES).update({ archived_at: null }).eq('id', gid);
  if (error) throw error;
  try{ if (typeof window.__sqClearGamesTruthCache === 'function') window.__sqClearGamesTruthCache('cloudReinstateGame'); }catch(_){ }
  try{ localStorage.removeItem('SQ_PSTICKER_CACHE_V1'); }catch(_){ }
  try{ if (typeof window.__sqRefreshRecentMatchesTicker==='function') window.__sqRefreshRecentMatchesTicker(); }catch(_){ }
  return true;
}

// Permanent purge: remove game row + best-effort cleanup of related tables.
// NOTE: This is intentionally destructive.
async function cloudPurgeGameCascade(game){
  await ensureCloudInit();
  const gid = (typeof game === 'object' && game) ? (game.id || game.game_id || null) : game;
  if (!gid) throw new Error('cloudPurgeGameCascade: missing game id');

  const tryDel = async (table, col='game_id')=>{
    try{ await sb.from(table).delete().eq(col, gid); }catch(_){ }
  };

  await tryDel(TABLE_HS_LEAGUE, 'game_id');
  await tryDel(TABLE_HS_PRACTICE, 'game_id');

  // Best-effort event/commentary cleanup (only if tables exist)
  await tryDel('game_events', 'game_id');
  await tryDel('game_commentary', 'game_id');

  // Throws table if ever enabled
  try{
    if (typeof TABLE_GAME_THROWS==='string' && TABLE_GAME_THROWS && !(CLOUD_TABLE_MISSING && CLOUD_TABLE_MISSING[TABLE_GAME_THROWS])){
      await tryDel(TABLE_GAME_THROWS, 'game_id');
    }
  }catch(_){ }

  const { error: delErr } = await sb.from(TABLE_GAMES).delete().eq('id', gid);
  if (delErr) throw delErr;
  try{ if (typeof window.__sqClearGamesTruthCache === 'function') window.__sqClearGamesTruthCache('cloudPurgeGameCascade'); }catch(_){ }
  return true;
}
// <<< PATCH:MOT5B3_ARCHIVE_REINSTATE_PURGE END

// >>> PATCH:MOT_STAGE5A_PROBE_EARLY_V4 START
// Ensure probe helpers exist even if later script sections bail early.
// Read-only: probes required Supabase tables/views and reports status.
(function(){
  try{
    // Contract items default to required:true unless explicitly set required:false (optional).
    if (!window.SQ_CLOUD_CONTRACT){
      window.SQ_CLOUD_CONTRACT = [
        { kind:'table', name: (typeof TABLE_GAMES!=='undefined'?TABLE_GAMES:'games'), usedBy:['cloudFetch*','getGamesForMode'], required:true },
        { kind:'table', name: (typeof TABLE_MATCHES!=='undefined'?TABLE_MATCHES:'matches'), usedBy:['cloudFetchAllMatchesAsLocal','getMatchesOfficial'], required:true },
        { kind:'view',  name: (typeof TABLE_PLAYER_GAMES!=='undefined'?TABLE_PLAYER_GAMES:'player_games_union'), usedBy:['stats windows'], required:true },
        { kind:'table', name: (typeof TABLE_HS_LEAGUE!=='undefined'?TABLE_HS_LEAGUE:'high_scores_sp'), usedBy:['High Score League'], required:true },
        { kind:'table', name: (typeof TABLE_HS_PRACTICE!=='undefined'?TABLE_HS_PRACTICE:'high_scores'), usedBy:['practice highs'], required:true },
        { kind:'view',  name: 'v_top50_scores_official', usedBy:['Top 50 modal'], required:true },
        { kind:'view',  name: 'v_round_high_scores_modal', usedBy:['Round High Scores modal'], required:true },

        // Optional clean app PB/WR views for runtime edging/admin snapshots.
        { kind:'view', name: (typeof TABLE_PB_ROUNDS_CLEAN_APP!=='undefined'?TABLE_PB_ROUNDS_CLEAN_APP:'v_pb_by_player_round_clean_app'), usedBy:['PB rounds'], required:false },
        { kind:'view', name: (typeof TABLE_WR_ROUNDS_CLEAN_APP!=='undefined'?TABLE_WR_ROUNDS_CLEAN_APP:'v_wr_by_round_clean_app'), usedBy:['WR rounds'], required:false }
      ];
    }

    var _lastProbe = null;

    function _isOptional(obj){ return obj && obj.required === false; }

    async function _probeOne(obj){
      const started = Date.now();
      const out = { kind: obj.kind, name: obj.name, required: (obj.required !== false), ok:false, missing:false, rowsUnknown:true, count:null, error:null, ms:0 };
      try{
        if (typeof ensureCloudInit === 'function' && !ensureCloudInit()){
          out.error = 'Cloud not initialised';
          out.ms = Date.now()-started;
          return out;
        }
        if (!window.sb){
          out.error = 'Supabase client missing (window.sb)';
          out.ms = Date.now()-started;
          return out;
        }
        const res = await window.sb.from(obj.name).select('*', { head:true, count:'exact' }).limit(1);
        if (res && res.error) throw res.error;
        out.ok = true;
        out.rowsUnknown = false;
        if (typeof res.count === 'number') out.count = res.count;
      }catch(e){
        const msg = String(e && (e.message || e.details || e.hint) || e || '');
        out.ok = false;
        out.error = msg || 'Probe failed';
        out.missing = /relation .* does not exist|Could not find the|404|Not Found|PGRST/i.test(out.error);

        // Only auto-mark required deps as missing; optional deps should not trip global guards.
        try{
          if (out.missing && out.required && typeof cloudMarkTableMissing === 'function') cloudMarkTableMissing(obj.name);
        }catch(_){}
      }
      out.ms = Date.now()-started;
      return out;
    }

    // sqCloudProbe({ includeOptional:true|false })  (default false to avoid noisy 404s in consoles)
    window.sqCloudProbe = window.sqCloudProbe || async function sqCloudProbe(opts){
      const o = opts || {};
      const includeOptional = !!o.includeOptional;

      const CONTRACT_ALL = window.SQ_CLOUD_CONTRACT || [];
      const CONTRACT = includeOptional ? CONTRACT_ALL : CONTRACT_ALL.filter(x => !_isOptional(x));

      const started = Date.now();
      const status = {
        at:new Date().toISOString(),
        ok:false,
        cloudInit:false,
        total:CONTRACT.length,
        requiredTotal: CONTRACT.filter(x => x.required !== false).length,
        okCount:0,
        missingCount:0,
        failedCount:0,
        okRequired:0,
        missingRequired:0,
        failedRequired:0,
        optionalMissing:0,
        items:[],
        ms:0,
        includeOptional
      };

      status.cloudInit = (typeof ensureCloudInit==='function') ? !!ensureCloudInit() : !!window.sb;

      const results = [];
      for (const obj of CONTRACT) results.push(await _probeOne(obj));

      status.items = results;

      const ok = results.filter(r=>r.ok);
      const missing = results.filter(r=>r.missing);
      const failed = results.filter(r=>(!r.ok && !r.missing));

      status.okCount = ok.length;
      status.missingCount = missing.length;
      status.failedCount = failed.length;

      const req = results.filter(r=>r.required);
      status.okRequired = req.filter(r=>r.ok).length;
      status.missingRequired = req.filter(r=>r.missing).length;
      status.failedRequired = req.filter(r=>(!r.ok && !r.missing)).length;

      const opt = results.filter(r=>!r.required);
      status.optionalMissing = opt.filter(r=>!r.ok).length;

      status.ok = (status.okRequired === status.requiredTotal) && (status.missingRequired === 0) && (status.failedRequired === 0);
      status.ms = Date.now()-started;
      _lastProbe = status;
      return status;
    };

    window.sqCloudContractStatus = window.sqCloudContractStatus || function(){ return _lastProbe; };

    window.sqCloudHealth = window.sqCloudHealth || function(){
      const s = _lastProbe;
      if (!s){
        console.log('[SQ CLOUD HEALTH] No probe run yet. Run: sqCloudProbeNow()');
        return { ok:false, msg:'No probe run yet' };
      }

      const reqMsg = s.ok
        ? `REQUIRED OK (${s.okRequired}/${s.requiredTotal})`
        : `REQUIRED NOT OK (ok:${s.okRequired}/${s.requiredTotal}, missing:${s.missingRequired}, fail:${s.failedRequired})`;

      const optMsg = s.includeOptional
        ? `OPTIONAL (missing:${s.optionalMissing})`
        : `OPTIONAL (skipped)`;

      const msg = `${reqMsg} • ${optMsg}`;

      console.log('[SQ CLOUD HEALTH]', msg, s);
      return { ok:!!s.ok, msg, status:s };
    };

    // Convenience: default probe is required-only (no optional noisy 404s)
    window.sqCloudProbeNow = window.sqCloudProbeNow || function(){
      return Promise.resolve(window.sqCloudProbe({ includeOptional:false })).then(()=>window.sqCloudHealth());
    };

    // Convenience: probe everything (will show optional misses if they truly don't exist)
    window.sqCloudProbeAllNow = window.sqCloudProbeAllNow || function(){
      return Promise.resolve(window.sqCloudProbe({ includeOptional:true })).then(()=>window.sqCloudHealth());
    };

  }catch(_e){}
})();
