      created_at: pick(g.created_at, ts, null),
      completed_at: pick(g.completed_at, state.completed_at, ts, null),
      mode: mode,
      isPractice: mode === 'practice',
      is_practice: mode === 'practice',
      isOfficial: mode === 'official',
