// >>> PATCH:player_stats_spider_progress START
(function(){
  function safeLower(s){return String(s||'').trim().toLowerCase();}
  function isoWeekStart(d){
    const x = (d instanceof Date) ? new Date(d) : new Date(d);
    if (Number.isNaN(x.getTime())) return null;
    // Monday start
    const day = (x.getDay()+6)%7; // Mon=0
    x.setHours(0,0,0,0);
    x.setDate(x.getDate()-day);
    return x;
  }

  function __sqSpiderRadiusNorm(valuePct){
    const p = Math.max(0, Math.min(100, Number(valuePct)||0));
    if (p <= 25) return (p / 25) * 0.5;
    if (p <= 75) return 0.5 + ((p - 25) / 50) * 0.25;
    return 0.75 + ((p - 75) / 25) * 0.25;
  }

  function drawRadar(canvas, labels, valuesPct, opts){
    const o = opts || {};
    const t = Math.max(0, Math.min(1, Number.isFinite(o.t) ? o.t : 1));
    const sel = Number.isFinite(o.sel) ? o.sel : null;
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0,0,W,H);

    const cx = W/2, cy = H/2;
    const R  = Math.min(W,H)*0.355;
    const N  = labels.length;
    const ang = i => (-Math.PI/2) + (i*2*Math.PI/N);

    // ambient blue glow behind the web
    const bg = ctx.createRadialGradient(cx,cy,R*0.1,cx,cy,R*1.45);
    bg.addColorStop(0,'rgba(47,134,255,0.12)');
    bg.addColorStop(0.65,'rgba(13,20,38,0)');
    ctx.fillStyle = bg; ctx.fillRect(0,0,W,H);

    // percentage rings follow the same nonlinear radius scale as the data.
    const ringPcts = [25, 50, 75, 100];
    for (let g=1; g<=ringPcts.length; g++){
      const r = R * __sqSpiderRadiusNorm(ringPcts[g-1]);
      ctx.beginPath();
      for (let i=0;i<N;i++){
        const x = cx + Math.cos(ang(i))*r, y = cy + Math.sin(ang(i))*r;
        if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
      }
      ctx.closePath();
      ctx.strokeStyle = g===ringPcts.length ? 'rgba(122,170,255,0.45)' : 'rgba(122,170,255,0.16)';
      ctx.lineWidth = g===ringPcts.length ? 1.4 : 1;
      ctx.stroke();
    }

    // spokes
    ctx.strokeStyle = 'rgba(122,170,255,0.14)';
    ctx.lineWidth = 1;
    for (let i=0;i<N;i++){
      ctx.beginPath();
      ctx.moveTo(cx,cy);
      ctx.lineTo(cx+Math.cos(ang(i))*R, cy+Math.sin(ang(i))*R);
      ctx.stroke();
    }

    // value points use the nonlinear display scale while retaining the real percentage.
    const pts = labels.map((_,i)=>{
      const pct = Math.max(0, Math.min(100, Number(valuesPct[i]||0)));
      const radius = __sqSpiderRadiusNorm(pct);
      return { x: cx + Math.cos(ang(i))*R*radius, y: cy + Math.sin(ang(i))*R*radius, v:pct };
    });
    let bi = 0; pts.forEach((p,i)=>{ if (p.v > pts[bi].v) bi = i; });

    const grad = ctx.createRadialGradient(cx,cy,0,cx,cy,R);
    grad.addColorStop(0,'rgba(255,122,0,0.40)');
    grad.addColorStop(1,'rgba(255,122,0,0.10)');

    if (t < 1){
      // Radar sweep: reveal the polygon around the dial like a scanner arm
      const sweep = t * N;
      const k = Math.max(1, Math.min(N, Math.ceil(sweep)));
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      for (let i=0;i<k;i++) ctx.lineTo(pts[i].x, pts[i].y);
      ctx.closePath();
      ctx.fillStyle = grad; ctx.globalAlpha = .9; ctx.fill(); ctx.globalAlpha = 1;
      ctx.save();
      ctx.shadowColor = 'rgba(255,140,40,0.85)'; ctx.shadowBlur = 12;
      ctx.strokeStyle = 'rgba(255,164,64,0.98)'; ctx.lineWidth = 2.2;
      ctx.beginPath();
      for (let i=0;i<k;i++){ if (i===0) ctx.moveTo(pts[i].x, pts[i].y); else ctx.lineTo(pts[i].x, pts[i].y); }
      ctx.stroke();
      ctx.restore();
      // scanner arm
      const armA = ang(0) + (t * 2 * Math.PI);
      ctx.save();
      ctx.shadowColor = 'rgba(255,180,80,1)'; ctx.shadowBlur = 14;
      ctx.strokeStyle = 'rgba(255,200,120,.9)'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(cx,cy);
      ctx.lineTo(cx + Math.cos(armA)*R, cy + Math.sin(armA)*R);
      ctx.stroke();
      ctx.restore();
    } else {
      // full polygon — Shateki orange fill with a neon stroke
      ctx.beginPath();
      pts.forEach((p,i)=>{ if (i===0) ctx.moveTo(p.x,p.y); else ctx.lineTo(p.x,p.y); });
      ctx.closePath();
      ctx.fillStyle = grad; ctx.fill();
      ctx.save();
      ctx.shadowColor = 'rgba(255,140,40,0.85)'; ctx.shadowBlur = 14;
      ctx.strokeStyle = 'rgba(255,164,64,0.98)'; ctx.lineWidth = 2.4;
      ctx.stroke();
      ctx.restore();

      // selection spotlight: bright spoke + big dot
      if (sel != null && pts[sel]){
        ctx.save();
        ctx.shadowColor = 'rgba(255,255,255,.7)'; ctx.shadowBlur = 8;
        ctx.strokeStyle = 'rgba(240,248,255,.85)'; ctx.lineWidth = 1.8;
        ctx.beginPath(); ctx.moveTo(cx,cy);
        ctx.lineTo(cx + Math.cos(ang(sel))*R, cy + Math.sin(ang(sel))*R);
        ctx.stroke();
        ctx.restore();
      }

      // vertex dots (best target glows green; selected gets a white core)
      pts.forEach((p,i)=>{
        const isSel = sel === i;
        ctx.save();
        ctx.shadowColor = isSel ? 'rgba(255,255,255,.95)' : (i===bi ? 'rgba(115,240,126,0.9)' : 'rgba(255,160,60,0.8)');
        ctx.shadowBlur = isSel ? 14 : (i===bi ? 12 : 8);
        ctx.fillStyle = isSel ? '#ffffff' : (i===bi ? '#73f07e' : '#ffb347');
        ctx.beginPath(); ctx.arc(p.x, p.y, isSel ? 5.6 : (i===bi ? 4.4 : 3.2), 0, Math.PI*2); ctx.fill();
        ctx.restore();
        if (isSel){
          ctx.strokeStyle = '#ffa440'; ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(p.x, p.y, 5.6, 0, Math.PI*2); ctx.stroke();
        }
      });
    }

    // labels with per-target % underneath (dim the rest while one is selected)
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const labelAlpha = .3 + .7 * t;
    for (let i=0;i<N;i++){
      const isSel = sel === i;
      const dim = (sel != null && !isSel) ? .55 : 1;
      const lx = cx + Math.cos(ang(i))*(R+26);
      const ly = cy + Math.sin(ang(i))*(R+26);
      ctx.globalAlpha = labelAlpha * dim;
      ctx.fillStyle = isSel ? '#ffffff' : 'rgba(240,248,255,0.96)';
      ctx.font = (isSel ? '900 15px' : '800 13px') + ' system-ui, -apple-system, Segoe UI, Roboto, Arial';
      ctx.fillText(String(labels[i]), lx, ly-6);
      ctx.fillStyle = isSel ? '#ffd9b0' : (i===bi ? 'rgba(115,240,126,0.95)' : 'rgba(150,185,230,0.85)');
      ctx.font = (isSel ? '800 12px' : '700 10px') + ' system-ui, -apple-system, Segoe UI, Roboto, Arial';
      ctx.fillText(Math.round(Number(valuesPct[i]||0)) + '%', lx, ly+8);
      ctx.globalAlpha = 1;
    }

    // subtle ring scale marks; positions reflect the nonlinear display scale.
    ctx.fillStyle = 'rgba(160,190,235,0.5)';
    ctx.font = '700 9px system-ui, -apple-system, Segoe UI, Roboto, Arial';
    [25, 50, 75, 100].forEach(function(mark){
      const y = cy - R * __sqSpiderRadiusNorm(mark) + (mark === 100 ? 10 : -4);
      ctx.fillText(String(mark), cx - 18, y);
    });
  }

  function drawMultiLine(canvas, xLabels, seriesMap){
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0,0,W,H);

    const padL=44, padR=10, padT=12, padB=34;
    const chartW = W - padL - padR;
    const chartH = H - padT - padB;

    // Y max fixed at 100%
    const maxY = 100;

    // axes
    ctx.globalAlpha = 0.35;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padL, padT);
    ctx.lineTo(padL, H-padB);
    ctx.lineTo(W-padR, H-padB);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // y labels
    ctx.fillStyle = 'rgba(255,255,255,0.75)';
    ctx.font = '12px system-ui, -apple-system, Segoe UI, Roboto, Arial';
    ctx.textAlign = 'right';
    ctx.fillText('100', padL-6, padT+12);
    ctx.fillText('50',  padL-6, padT + chartH/2 + 4);
    ctx.fillText('0',   padL-6, H-padB);

    const n = xLabels.length || 1;
    const stepX = (n<=1) ? chartW : (chartW/(n-1));

    // x labels sparse
    ctx.textAlign = 'center';
    const step = Math.ceil(n/6);
    for (let i=0;i<n;i+=step){
      const lab = xLabels[i] || '';
      const x = padL + i*stepX;
      ctx.fillText(lab, x, H-10);
    }

    const keys = Object.keys(seriesMap||{});
    const palette = ['#34d399','#60a5fa','#f472b6','#fbbf24','#a78bfa','#fb7185','#22d3ee','#c084fc','#86efac','#fde047','#93c5fd','#fda4af','#fca5a5','#67e8f9'];
    keys.forEach((k, idx)=>{
      const vals = seriesMap[k] || [];
      const col = palette[idx % palette.length];
      ctx.strokeStyle = col;
      ctx.lineWidth = (idx===0? 2.8 : 2.2);
      ctx.beginPath();
      for (let i=0;i<n;i++){
        const v = Number(vals[i]);
        const yy = Number.isFinite(v) ? v : 0;
        const x = padL + i*stepX;
        const y = (H-padB) - (yy/maxY)*chartH;
        if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
      }
      ctx.stroke();
    });
  }

  async function fetchPlayerThrowsWithTs(playerName){
    const name = String(playerName||'').trim();
    const nameLC = safeLower(name);

    // --- Preferred: Supabase canonical view (one row per throw) ---
    // Columns (confirmed): match_id, game_number, created_at, player_index, player_name,
    // round_number, target, ring, hit
    // NOTE: This view is read-only; ideal for analytics.
    try{
      if (typeof ensureCloudInit === 'function' && !ensureCloudInit()) throw new Error('Cloud not initialised');
      if (!sb) throw new Error('Supabase client missing');

      const VIEW = 'throw_events_v';

      const selectCols = 'created_at,player_name,round_number,target,ring,hit';
      const rows = [];
      const PAGE = 1000;
      const MAX = 50000;

      for (let from = 0; from < MAX; from += PAGE){
        const to = from + PAGE - 1;
        const { data, error } = await sb
          .from(VIEW)
          .select(selectCols)
          .ilike('player_name', name)
          .order('created_at', { ascending: true })
          .range(from, to);
        if (error) throw error;
        if (Array.isArray(data) && data.length) rows.push(...data);
        if (!Array.isArray(data) || data.length < PAGE) break;
      }

      // Map view row -> internal throw row used by SPIDER/PROGRESS
      const mapped = (rows||[]).map(r => {
        const rn = Number(r.round_number);
        let round_index = null;

        // Robust mapping: different schemas encode rounds differently.
        // Supported encodings:
        //  A) round_number = 10..20 (numbers), 21 (Doubles), 22 (Triples), 23 (Bull)
        //  B) round_number = 1..11 (maps to 10..20), 12 (Doubles), 13 (Triples), 14 (Bull)
        //  C) round_number = 0..13 (direct index)

        if (Number.isFinite(rn)) {
          // C) direct index
          if (rn >= 0 && rn <= 13) {
            round_index = rn;
          }
          // B) 1..11 -> 10..20, then 12/13/14
          else if (rn >= 1 && rn <= 11) {
            round_index = rn - 1;
          } else if (rn === 12) {
            round_index = 11;
          } else if (rn === 13) {
            round_index = 12;
          } else if (rn === 14) {
            round_index = 13;
          }
          // A) 10..20, 21/22/23
          else if (rn >= 10 && rn <= 20) {
            round_index = rn - 10;
          } else if (rn === 21) {
            round_index = 11;
          } else if (rn === 22) {
            round_index = 12;
          } else if (rn === 23) {
            round_index = 13;
          }
        }

        // Last-resort fallback: infer from target/ring
        if (round_index == null) {
          const ring = String(r.ring || '').trim().toUpperCase();
          const target = Number(r.target);
          if (Number.isFinite(target) && target >= 10 && target <= 20) round_index = target - 10;
          else if (ring === 'D') round_index = 11;
          else if (ring === 'T') round_index = 12;
          else if (ring === 'B' || ring === 'IB' || ring === 'OB') round_index = 13;
        }

                const ts = r.created_at || null;

        const ri = (typeof round_index === 'number') ? round_index : null;
        const ringU = String(r.ring || '').trim().toUpperCase();
        const targetN = Number(r.target);

        // Normalise ring -> kind used by the app
        const kind =
          (ringU === 'D')  ? 'd'  :
          (ringU === 'T')  ? 't'  :
          (ringU === 'IB') ? 'ib' :
          (ringU === 'OB') ? 'ob' :
          (ringU === 'B')  ? 'b'  :
          's';

        // Canonical Target Hit% "hit" definition (do NOT trust view.hit)
        const hit =
          (ri != null && ri >= 0 && ri <= 10) ? (ringU === 'S' || ringU === 'D' || ringU === 'T') :
          (ri === 11) ? (ringU === 'D') :
          (ri === 12) ? (ringU === 'T') :
          (ri === 13) ? (ringU === 'IB' || ringU === 'OB' || ringU === 'B') :
          false;

        // Points (robust for any points-based stat elsewhere)
        let points = 0;
        if (hit && ri != null) {
          if (ri >= 0 && ri <= 10) {
            const base = 10 + ri;
            points = (ringU === 'D') ? base * 2 : (ringU === 'T') ? base * 3 : base;
          } else if (ri === 11) {
            points = Number.isFinite(targetN) ? targetN * 2 : 0;
          } else if (ri === 12) {
            points = Number.isFinite(targetN) ? targetN * 3 : 0;
          } else if (ri === 13) {
            if (ringU === 'IB') points = 50;
            else if (ringU === 'OB') points = 25;
            else if (ringU === 'B') points = (targetN === 25) ? 25 : 50;
          }
        }

        return {
          game_id: r.match_id || null,
          player: r.player_name || name,
          round_index,
          dart_index: null,
          points,
          kind,
          hit,
          ts
        };
      }).filter(x => safeLower(x.player) === nameLC);

      return mapped;
    }catch(e){
      console.warn('[throws] throw_events_v not available, falling back to game boards', e);
    }

    // --- Fallback: reconstruct from official games (local-normalised) ---
    const gamesAll = (await __fetchOfficialGames(50000)).map(__normalizeGame);
    const rows = __throwsFromGamesForPlayer(name, gamesAll);
    // Attach timestamps from games if available
    const gameTs = new Map();
    gamesAll.forEach(g => {
      const gid = (g.raw && (g.raw.id || g.raw.game_id)) || g.id || g.game_id;
      if (gid && g.ts) gameTs.set(gid, g.ts);
    });

    return (rows||[]).map(r => {
      const ts = r.ts || gameTs.get(r.game_id) || null;
      const hit = Number(r.points||0) > 0;
      return Object.assign({}, r, { ts, hit });
    }).filter(r => safeLower(r.player) === nameLC);
  }

  function __sqDrawSpiderComparisonOverlay(canvas, labels, valuesPct, opts){
    if (!canvas || !Array.isArray(labels) || !labels.length || !Array.isArray(valuesPct)) return;
    var ctx = canvas.getContext('2d');
    var W = canvas.width, H = canvas.height;
    var cx = W / 2, cy = H / 2, R = Math.min(W, H) * 0.355;
    var N = labels.length, t = Math.max(0, Math.min(1, Number(opts && opts.t == null ? 1 : opts.t)));
    var pts = [];
    for (var i=0;i<N;i++){
      var raw = Number(valuesPct[i]);
      if (!Number.isFinite(raw)){ pts.push(null); continue; }
      var v = __sqSpiderRadiusNorm(raw);
      var a = -Math.PI / 2 + (i * Math.PI * 2 / N);
      pts.push({ x:cx + Math.cos(a) * R * v * t, y:cy + Math.sin(a) * R * v * t });
    }
    ctx.save();
    ctx.strokeStyle = '#7dd3fc';
    ctx.lineWidth = 2.6;
    ctx.setLineDash([8,5]);
    ctx.shadowColor = 'rgba(125,211,252,.7)';
    ctx.shadowBlur = 8;
    var complete = pts.every(function(p){ return !!p; });
    if (complete){
      ctx.beginPath();
      pts.forEach(function(p,i){ if (i === 0) ctx.moveTo(p.x,p.y); else ctx.lineTo(p.x,p.y); });
      ctx.closePath(); ctx.stroke();
    } else {
      var drawing = false;
      pts.forEach(function(p){
        if (!p){ if (drawing){ ctx.stroke(); drawing = false; } return; }
        if (!drawing){ ctx.beginPath(); ctx.moveTo(p.x,p.y); drawing = true; }
        else ctx.lineTo(p.x,p.y);
      });
      if (drawing) ctx.stroke();
    }
    ctx.setLineDash([]);
    ctx.shadowBlur = 0;
    pts.forEach(function(p){
      if (!p) return;
      ctx.fillStyle = '#08111f';
      ctx.strokeStyle = '#e9fbff';
      ctx.lineWidth = 1.5;
      ctx.fillRect(p.x - 3.5, p.y - 3.5, 7, 7);
      ctx.strokeRect(p.x - 3.5, p.y - 3.5, 7, 7);
    });
    ctx.restore();
  }

  window.openPlayerSpiderDialog = async function openPlayerSpiderDialog(playerName, opts){
    const name = String(playerName||'').trim();
    const overlay = document.createElement('div'); overlay.className='modal-backdrop';
    const modal   = document.createElement('div'); modal.className  ='modal';
  modal.style.maxWidth='980px'; modal.style.width='94vw';
    const title   = document.createElement('h3');  title.textContent=`SPIDER — ${name}`;
    const body    = document.createElement('div'); body.className   ='modal-body';
    const footer  = document.createElement('div'); footer.className ='modal-footer';
    modal.style.maxHeight='90vh'; modal.style.overflow='hidden';
    body.style.maxHeight='none'; body.style.overflowY='visible';

    const wrap = document.createElement('div');
    wrap.style.display='flex';
    wrap.style.flexDirection='column';
    wrap.style.alignItems='center';
    wrap.style.gap='10px';

    const canvas = document.createElement('canvas');
    canvas.width = 360; canvas.height = 360;
    canvas.style.width = 'min(360px, 92vw)';
    canvas.style.height= 'auto';
    canvas.style.borderRadius = '14px';
    canvas.style.border = '1px solid rgba(35,164,255,.25)';
    canvas.style.background = 'radial-gradient(circle at 50% 42%, rgba(37,58,114,.5), rgba(10,16,38,.95) 66%, rgba(4,7,18,.98))';
    canvas.style.boxShadow = '0 10px 26px rgba(0,0,0,.4), 0 0 24px rgba(47,134,255,.10)';

    const note = document.createElement('div');
    note.className='muted';
    note.style.cssText='display:flex;justify-content:center;gap:10px;flex-wrap:wrap;min-height:30px;align-items:center;';
    note.textContent='Loading…';

    const compareRows = opts && opts.data && Array.isArray(opts.data.comparePlayers) ? opts.data.comparePlayers : [];
    const compareBar = document.createElement('div');
    compareBar.className = 'sq-spider-compare-bar';
    compareBar.style.cssText = 'width:100%;display:flex;justify-content:flex-end;align-items:center;gap:8px;';
    const compareLabel = document.createElement('label'); compareLabel.textContent = 'Compare';
    compareLabel.style.cssText = 'font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:rgba(190,215,245,.82);';
    const compareSelect = document.createElement('select');
    compareSelect.className = 'sq-spider-compare-select';
    compareSelect.setAttribute('aria-label', 'Compare player');
    compareSelect.style.cssText = 'max-width:min(220px,58vw);background:#0d1424;color:#eaf5ff;border:1px solid rgba(125,211,252,.52);border-radius:9px;padding:7px 9px;font-weight:800;';
    var compareNone = document.createElement('option'); compareNone.value = ''; compareNone.textContent = 'Choose player...'; compareSelect.appendChild(compareNone);
    compareRows.forEach(function(pl, i){ var op = document.createElement('option'); op.value = String(i); op.textContent = String(pl.name || pl.key || ''); compareSelect.appendChild(op); });
    compareBar.append(compareLabel, compareSelect);
    if (!compareRows.length) compareBar.style.display = 'none';
    const compareLegend = document.createElement('div');
    compareLegend.className = 'sq-spider-compare-legend';
    compareLegend.style.cssText = 'display:none;width:100%;justify-content:center;gap:14px;flex-wrap:wrap;font-size:10px;font-weight:850;color:#dcecff;';
    let activeCompare = null;
    const renderCompareLegend = () => {
      compareLegend.innerHTML = '';
      if (!activeCompare){ compareLegend.style.display = 'none'; return; }
      compareLegend.style.display = 'flex';
      const mk = (label, dashed) => { const el = document.createElement('span'); el.style.cssText='display:inline-flex;align-items:center;gap:6px;'; const sw=document.createElement('i'); sw.style.cssText='display:inline-block;width:24px;border-top:3px ' + (dashed ? 'dashed #7dd3fc' : 'solid #ffa440') + ';'; const tx=document.createElement('span'); tx.textContent=label; el.append(sw,tx); return el; };
      compareLegend.append(mk(name, false), mk(String(activeCompare.name || activeCompare.key || ''), true));
    };
    // Summary chips: selected target (when tapped) + BEST / FOCUS
    const renderSummary = (labels, pct, selIdx) => {
      try{
        const vals = (labels||[]).map((l,i)=>({ l:String(l), v:Number(pct && pct[i] || 0) })).filter(x=>Number.isFinite(x.v));
        if (!vals.length){ note.textContent=''; return; }
        const best = vals.reduce((a,b)=> b.v>a.v?b:a);
        const worst = vals.reduce((a,b)=> b.v<a.v?b:a);
        const chip = (label, val, color) =>
          '<span style="display:inline-flex;align-items:center;gap:7px;padding:6px 14px;border-radius:99px;'
          + 'background:#101827;border:1px solid ' + color + ';color:#e8f4ff;font-weight:800;font-size:12px;letter-spacing:.06em;">'
          + label + ' <b style="color:' + color + ';font-size:13px;">' + val + '</b></span>';
        let html = '';
        if (selIdx != null && labels[selIdx] != null){
          html += chip('TARGET ' + labels[selIdx], Math.round(Number(pct[selIdx]||0)) + '%', 'rgba(255,255,255,.9)');
        }
        html += chip('BEST ' + best.l, Math.round(best.v) + '%', 'rgba(115,240,126,.9)')
             +  chip('FOCUS ' + worst.l, Math.round(worst.v) + '%', 'rgba(255,140,40,.9)');
        note.innerHTML = html;
      }catch(_e){ note.textContent=''; }
    };

    // Radar-sweep reveal + tap a spoke/label to spotlight one target
    let spiderRaf = 0;
    const paintRadar = (labels, pct, sel, t) => {
      drawRadar(canvas, labels, pct, { t:t, sel:sel });
      if (activeCompare && Array.isArray(activeCompare.pct)) __sqDrawSpiderComparisonOverlay(canvas, labels, activeCompare.pct, { t:t });
      canvas.dataset.sqCompare = activeCompare ? String(activeCompare.name || activeCompare.key || '') : '';
    };
    const showRadar = (labels, pct) => {
      canvas.__sqSpider = { labels, pct, sel:null, compare:activeCompare };
      cancelAnimationFrame(spiderRaf);
      let reduce = false;
      try{ reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; }catch(_e){}
      const dur = reduce ? 0 : 780;
      const start = performance.now();
      const step = now => {
        const raw = dur ? Math.min(1, (now - start) / dur) : 1;
        paintRadar(labels, pct, null, raw);
        if (raw < 1) spiderRaf = requestAnimationFrame(step);
      };
      spiderRaf = requestAnimationFrame(step);
      renderSummary(labels, pct, null);
    };
    canvas.style.cursor = 'pointer';
    canvas.addEventListener('click', e => {
      const s = canvas.__sqSpider;
      if (!s || !s.labels || !s.labels.length) return;
      const r = canvas.getBoundingClientRect();
      const scale = canvas.width / Math.max(1, r.width);
      const x = (e.clientX - r.left) * scale, y = (e.clientY - r.top) * scale;
      const cx = canvas.width / 2, cy = canvas.height / 2;
      const dx = x - cx, dy = y - cy;
      const R = Math.min(canvas.width, canvas.height) * 0.355;
      if (Math.hypot(dx, dy) > R + 44) return;
      const N = s.labels.length;
      let theta = Math.atan2(dy, dx) + Math.PI / 2;
      if (theta < 0) theta += Math.PI * 2;
      const idx = Math.round(theta / (2 * Math.PI / N)) % N;
      s.sel = (s.sel === idx) ? null : idx;
      cancelAnimationFrame(spiderRaf);
      paintRadar(s.labels, s.pct, s.sel, 1);
      renderSummary(s.labels, s.pct, s.sel);
    });

    compareSelect.onchange = () => {
      activeCompare = compareSelect.value === '' ? null : (compareRows[Number(compareSelect.value)] || null);
      const s = canvas.__sqSpider;
      if (s){ s.compare = activeCompare; paintRadar(s.labels, s.pct, s.sel, 1); }
      renderCompareLegend();
    };

    wrap.append(compareBar, canvas, compareLegend, note);
    body.appendChild(wrap);

    const backBtn=document.createElement('button'); backBtn.className='btn sq-pill'; backBtn.textContent='Back';
    const parentOverlay = opts && opts.parentOverlay ? opts.parentOverlay : null;
    const backToPrev = () => {
      overlay.remove();
      if (parentOverlay){ parentOverlay.style.display=''; try{ parentOverlay.querySelector('.modal')?.focus?.(); }catch(_e){} return; }
      if (typeof window.openPlayerStatsModePicker==='function') window.openPlayerStatsModePicker(name);
      else if (typeof window.openPlayerStatsHub==='function') window.openPlayerStatsHub(name);
    };
    backBtn.onclick = backToPrev;
    footer.append(backBtn);

    modal.append(title, body, footer);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    __sqStatsArcade(overlay, modal);
    overlay.addEventListener('click',e=>{ if(e.target===overlay) backToPrev();});
    overlay.addEventListener('keydown',e=>{ if(e.key==='Escape') backToPrev();});
    modal.tabIndex=0; modal.focus();

    try{
      const mode = (opts && opts.mode) ? String(opts.mode).toLowerCase() : 'hit';
      const data = (opts && opts.data) ? opts.data : null;

      if (mode === 'points' && data && Array.isArray(data.labels) && Array.isArray(data.pct)) {
        const labels = data.labels.slice();
        const pct = data.pct.slice();
        showRadar(labels, pct);
        return;
      }

      if (mode === 'dtb' && data && Array.isArray(data.labels) && Array.isArray(data.pctD) && Array.isArray(data.pctT)) {
        const labels = data.labels.slice();
        const pctD = data.pctD.slice();
        const pctT = data.pctT.slice();

        const toggleRow = document.createElement('div');
        toggleRow.className='row';
        toggleRow.style.gap='8px';
        toggleRow.style.justifyContent='center';
        toggleRow.style.flexWrap='wrap';
        toggleRow.dataset.dtbToggle='1';

        const btnD = document.createElement('button'); btnD.className='btn small primary'; btnD.textContent='DOUBLES';
        const btnT = document.createElement('button'); btnT.className='btn small'; btnT.textContent='TREBLES';

        let which = 'd';
        const renderDTB = () => {
          if (which === 'd') {
            btnD.classList.add('primary'); btnT.classList.remove('primary');
            showRadar(labels, pctD);
          } else {
            btnT.classList.add('primary'); btnD.classList.remove('primary');
            showRadar(labels, pctT);
          }
        };

        btnD.onclick = ()=>{ which='d'; renderDTB(); };
        btnT.onclick = ()=>{ which='t'; renderDTB(); };

        if (!wrap.querySelector('[data-dtb-toggle="1"]')) {
          toggleRow.append(btnD, btnT);
          wrap.insertBefore(toggleRow, canvas);
        }

        renderDTB();
        return;
      }

      // Default: Hit % spider (10–20, D, T, B)
      const labels = (data && Array.isArray(data.labels)) ? data.labels : __roundLabels();
      let pct = (data && Array.isArray(data.pct)) ? data.pct.slice(0, labels.length) : null;

      if (!pct){
        const rows = await fetchPlayerThrowsWithTs(name);
        const taken = Array(14).fill(0), hits = Array(14).fill(0);
        rows.forEach(t=>{
          const r = (typeof t.round_index==='number') ? t.round_index : null;
          if (r==null || r<0 || r>13) return;
          taken[r] += 1;
          if ((t.hit===true) || (Number(t.points||0)>0)) hits[r] += 1;
        });
        pct = taken.map((n,i)=> n ? (100*hits[i]/n) : 0);
      }

      showRadar(labels, pct);
    }catch(e){
      console.error('SPIDER failed', e);
      note.textContent = 'Could not load data.';
    }
  };

  window.openPlayerProgressHitDialog = async function openPlayerProgressHitDialog(playerName, opts={}){
    const name = String(playerName||'').trim();
    const mode = String((opts && opts.mode) || 'hit').toLowerCase(); // hit | points | dtb
    const parentOverlay = opts && opts.parentOverlay ? opts.parentOverlay : null;

    // --- modal shell (match Game Race / Progression styling) ---
    const overlay = document.createElement('div'); overlay.className='modal-backdrop';
    const modal   = document.createElement('div'); modal.className='modal wide';
    modal.style.maxWidth = '920px';
    modal.style.width = 'min(920px, 96vw)';
    modal.style.maxHeight = '90vh';
    modal.style.overflow = 'hidden';

    const title = document.createElement('h3');
    title.textContent = (mode==='points') ? `TARGET POINTS % — ${name}` : (mode==='dtb' ? `DTB % — ${name}` : `TARGET HIT % — ${name}`);

    const body = document.createElement('div'); body.className='modal-body';
    body.style.overflow = 'auto'; body.style.overflowY = 'hidden';

    const footer = document.createElement('div'); footer.className='modal-footer';
    const backBtn=document.createElement('button'); backBtn.className='btn sq-pill'; backBtn.textContent='Back';

    const backToPrev = () => {
      overlay.remove();
      if (parentOverlay){ parentOverlay.style.display=''; try{ parentOverlay.querySelector('.modal')?.focus?.(); }catch(_e){} return; }
      if (typeof window.openPlayerStatsModePicker==='function') window.openPlayerStatsModePicker(name);
      else if (typeof window.openPlayerStatsHub==='function') window.openPlayerStatsHub(name);
    };
    backBtn.onclick = backToPrev;
    footer.append(backBtn);

    // --- controls ---
    const controls = document.createElement('div');
    controls.style.display='flex';
    controls.style.flexDirection='column';
    controls.style.gap='10px';

    const avgRow = document.createElement('div');
    avgRow.style.display='flex';
    avgRow.style.gap='8px';
    avgRow.style.flexWrap='wrap';

    const avgBtns = [
      { key:'game4', label:'4 Game AV' },
      { key:'avg10', label:'10 Game AV' },
      { key:'avg20', label:'20 Game AV' }
    ];

    const targetRow = document.createElement('div');
    targetRow.style.display='flex';
    targetRow.style.gap='8px';
    targetRow.style.flexWrap='wrap';

    // Targets: 10..20 plus D/T/B (single-select)
    const targets = [];
    for (let n=10;n<=20;n++) targets.push({ key:String(n), label:String(n) });
    targets.push({ key:'D', label:'D' }, { key:'T', label:'T' }, { key:'B', label:'B' });

    let selectedTarget = '10';
    let avgMode = (opts && opts.avgMode) ? String(opts.avgMode) : 'game4';
    if (!['game4','avg10','avg20'].includes(avgMode)) avgMode = 'game4';

    function makePillButton(label, isActive=false){
      const b=document.createElement('button');
      b.className='btn tiny';
      b.textContent=label;
      b.style.borderRadius='999px';
      b.style.padding='6px 10px';
      b.style.fontSize='12px';
      b.style.letterSpacing='.06em';
      b.style.textTransform='uppercase';
      b.style.opacity = isActive ? '1' : '.75';
      b.style.borderColor = isActive ? 'rgba(255,140,0,.65)' : 'rgba(255,255,255,.14)';
      b.style.boxShadow = isActive ? '0 0 0 2px rgba(255,140,0,.10) inset' : 'none';
      return b;
    }

    function renderButtons(){
      avgRow.innerHTML='';
      avgBtns.forEach(it=>{
        const b = makePillButton(it.label, avgMode===it.key);
        b.onclick = () => { avgMode = it.key; renderButtons(); draw(); };
        avgRow.appendChild(b);
      });

      targetRow.innerHTML='';
      targets.forEach(it=>{
        const b = makePillButton(it.label, selectedTarget===it.key);
        b.onclick = () => { selectedTarget = it.key; renderButtons(); draw(); };
        targetRow.appendChild(b);
      });
    }

    // --- chart ---
    const canvas = document.createElement('canvas');
    canvas.width = 860;
    canvas.height = 420;
    canvas.style.width = 'auto'; canvas.style.display='block';
    canvas.style.height = 'auto';
    canvas.style.borderRadius = '14px';
    canvas.style.background = 'rgba(0,0,0,.18)';
    canvas.style.border = '1px solid rgba(255,255,255,.08)';

    const note = document.createElement('div');
    note.className='muted';
    note.style.display='flex';
    note.style.justifyContent='space-between';
    note.style.gap='10px';
    note.style.marginTop='6px';
    note.style.fontSize='12px';
    note.innerHTML = '';

    controls.appendChild(avgRow);
    controls.appendChild(targetRow);

    body.appendChild(controls);
    body.appendChild(canvas);
    body.appendChild(note);

    modal.append(title, body, footer);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    __sqStatsArcade(overlay, modal);
    overlay.addEventListener('click',e=>{ if(e.target===overlay) backToPrev();});
    overlay.addEventListener('keydown',e=>{ if(e.key==='Escape') backToPrev();});
    modal.tabIndex=0; modal.focus();

    // --- data ---
    let rows = null;
    try{
      if (opts && opts.data && Array.isArray(opts.data.throws)) rows = opts.data.throws;
      else rows = await fetchPlayerThrowsWithTs(name);
    }catch(e){
      console.warn('progress fetch failed', e);
      rows = [];
    }

    // Normalise game ordering (old data may not include game_id; treat null as one bucket)
    const games = new Map(); // gid -> { tsMax, byRound: Map(ri -> [throws]) }
    const safeGid = (r, i) => (r && r.game_id) ? String(r.game_id) : `local_${i}`;

    (rows||[]).forEach((r,i)=>{
      const gid = safeGid(r,i);
      if (!games.has(gid)) games.set(gid, { tsMax: null, byRound: new Map() });
      const g = games.get(gid);
      const ts = r && r.ts ? new Date(r.ts).getTime() : null;
      if (ts!=null && (g.tsMax==null || ts>g.tsMax)) g.tsMax = ts;

      const ri = Number(r.round_index);
      if (!Number.isFinite(ri)) return;
      if (!g.byRound.has(ri)) g.byRound.set(ri, []);
      g.byRound.get(ri).push(r);
    });

    // Order games by timestamp asc (fallback to insertion order)
    const gameList = Array.from(games.entries()).map(([gid, g]) => ({ gid, tsMax: g.tsMax, byRound: g.byRound }));
    gameList.sort((a,b)=>{
      const at=a.tsMax??0, bt=b.tsMax??0;
      return at-bt;
    });

    function roundIndexFromKey(key){
      if (key==='D') return 11;
      if (key==='T') return 12;
      if (key==='B') return 13;
      const n = Number(key);
      if (Number.isFinite(n) && n>=10 && n<=20) return n-10;
      return 0;
    }

    function pointsForThrow(r){
      const hit = !!(r && (r.hit || Number(r.points||0)>0));
      if (!hit) return 0;
      const ri = Number(r.round_index);
      const base = (ri>=0 && ri<=10) ? (10+ri) : (ri===11 ? 20 : (ri===12 ? 20 : (ri===13 ? 50 : 0)));
      const k = String(r.kind||'').toLowerCase();
      if (k==='d') return base*2;
      if (k==='t') return base*3;
      if (k==='ib') return 50;
      if (k==='ob') return 25;
      if (k==='b') return base; // if base is 50
      return base; // single/default
    }

    function maxPointsPerDart(ri){
      if (ri>=0 && ri<=10) return (10+ri)*3;
      if (ri===11) return 40;
      if (ri===12) return 60;
      if (ri===13) return 50;
      return 0;
    }

    function calcValueForRound(ri, throws){
      const darts = (throws||[]);
      const attempts = darts.length || 0;
      if (!attempts) return null;

      if (mode === 'points'){
        const sumPts = darts.reduce((a,r)=>a+pointsForThrow(r),0);
        const maxPts = attempts * maxPointsPerDart(ri);
        return maxPts>0 ? (sumPts/maxPts)*100 : 0;
      }

      if (mode === 'dtb'){
        let ok = 0;
        darts.forEach(r=>{
          const hit = !!(r && (r.hit || Number(r.points||0)>0));
          if (!hit) return;
          const k = String(r.kind||'').toLowerCase();
          if (ri>=0 && ri<=10){
            if (k==='d' || k==='t') ok++;
          }else if (ri===11){
            if (k==='d') ok++;
          }else if (ri===12){
            if (k==='t') ok++;
          }else if (ri===13){
            if (k==='ib' || k==='ob' || k==='b') ok++;
          }
        });
        return (ok/attempts)*100;
      }

      // default: hit%
      const hits = darts.reduce((a,r)=>a + ( (r && (r.hit || Number(r.points||0)>0)) ? 1 : 0 ), 0);
      return (hits/attempts)*100;
    }

    function computeSeries(targetKey){
      const ri = roundIndexFromKey(targetKey);
      const xs = []; // game indices (1..N)
      const ys = []; // values (0..100)
      gameList.forEach((g, idx)=>{
        const arr = g.byRound.get(ri) || [];
        const v = calcValueForRound(ri, arr);
        if (v==null) return; // skip games missing that round (rare)
        xs.push(idx+1);
        ys.push({ i: idx+1, v });
      });
      return { xs, ys, ri };
    }

    function rollingAvg(ys, win){
      const out=[];
      for (let i=0;i<ys.length;i++){
        const s = Math.max(0, i-win+1);
        let sum=0, c=0;
        for (let j=s;j<=i;j++){ const v=ys[j]; if (Number.isFinite(v)){ sum+=v; c++; } }
        out.push(c?sum/c:null);
      }
      return out;
    }

    function bucketLine(ys, bucketSize){
      const pts=[]; // {xIndex, y}
      for (let i=0;i<ys.length;i+=bucketSize){
        const slice=ys.slice(i, i+bucketSize);
        const vals=slice.filter(v=>Number.isFinite(v));
        const avg=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;
        pts.push({ x:i, y:avg });
      }
      return pts;
    }

    function trajectoryLine(ys){
      const n=ys.length;
      if (!n) return null;
      const mid = Math.floor(n/2);
      const a1 = ys.slice(0, mid).filter(v=>Number.isFinite(v));
      const a2 = ys.slice(mid).filter(v=>Number.isFinite(v));
      const y1 = a1.length? a1.reduce((a,b)=>a+b,0)/a1.length : null;
      const y2 = a2.length? a2.reduce((a,b)=>a+b,0)/a2.length : null;
      return { y1, y2 };
    }

    function drawChart(series){
      series = Array.isArray(series) ? series : [];
      const ys = series.map(d=>d.v);
      const n = ys.length;

      // Bar chart like Progression: squeeze bars to fit the popup (no horizontal scroll)
      const BASE_W = 920;
      const BASE_H = 420;
      const host = canvas.parentElement || canvas;
      const cssW = Math.max(320, Math.min(BASE_W, host.clientWidth || BASE_W));
      const cssH = BASE_H;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.round(cssW * dpr);
      canvas.height = Math.round(cssH * dpr);
      canvas.style.width = cssW + 'px';
      canvas.style.height = cssH + 'px';

      const ctx = canvas.getContext('2d');

      ctx.setTransform(dpr,0,0,dpr,0,0);
      const W = cssW, H = cssH;
      ctx.clearRect(0,0,W,H);

      const padL = 44, padR = 18, padT = 18, padB = 34;

      const innerW = W - padL - padR;
      const innerH = H - padT - padB;

      // Percent-style charts: fixed axis
      const yMin = 0, yMax = 100;

      const step = innerW / Math.max(1, n);
      const barW = Math.max(1, Math.min(6, step * 0.85));
      const xLeftForIndex = (i) => padL + i*step + (step - barW)/2;
      const xForIndex = (i) => xLeftForIndex(i) + barW/2;
      const yForVal = (v) => padT + (1 - ((v - yMin)/(yMax-yMin))) * innerH;

      // grid
      ctx.strokeStyle='rgba(255,255,255,.08)';
      ctx.lineWidth=1;
      for (let g=0; g<=5; g++){
        const y = padT + (innerH*(g/5));
        ctx.beginPath(); ctx.moveTo(padL,y); ctx.lineTo(W-padR,y); ctx.stroke();
      }

      // bars
      ctx.fillStyle='rgba(255,255,255,.35)';
      for (let i=0;i<n;i++){
        const v = ys[i];
        const x = xLeftForIndex(i);
        const y = yForVal(v);
        const h = (padT+innerH) - y;
        ctx.fillRect(x, y, barW, h);
      }

      // average line modes
      const mode = (avgMode==='avg10' || avgMode==='avg20' || avgMode==='game4') ? avgMode : 'game4';
      const linePts = [];
      const winMap = { game4:4, avg10:10, avg20:20 };
      const win = winMap[mode] || 4;
      if (n){
        for (let i=0;i<n;i++){
          const s = Math.max(0, i-win+1);
          const seg = ys.slice(s, i+1);
          const av = seg.reduce((a,b)=>a+b,0) / seg.length;
          linePts.push({x:xForIndex(i), y:yForVal(av)});
        }
      }
// Always show all-time avg as dotted orange
      if (allTimeAvg != null){
        const y = yForVal(allTimeAvg);
        ctx.setLineDash([3,4]);
        ctx.strokeStyle='rgba(255,140,0,.95)';
        ctx.lineWidth=2;
        ctx.beginPath(); ctx.moveTo(padL,y); ctx.lineTo(W-padR,y); ctx.stroke();
        ctx.setLineDash([]);
      }

      // green line (selected mode)
      if (linePts.length){
        ctx.strokeStyle='rgba(140,255,140,.85)';
        ctx.lineWidth=2;
        ctx.beginPath();
        ctx.moveTo(linePts[0].x, linePts[0].y);
        for (let i=1;i<linePts.length;i++) ctx.lineTo(linePts[i].x, linePts[i].y);
        ctx.stroke();
      }

      // x labels (sparse, like progression)
      ctx.fillStyle='rgba(255,255,255,.35)';
      ctx.font='11px system-ui, -apple-system, Segoe UI, Roboto';
      const stepLab = (n<=40)?5:(n<=120?10:20);
      for (let i=0;i<n;i++){
        if (i===0 || i===n-1 || (i%stepLab===0)){
          const tx = xForIndex(i);
          const lbl = String(series[i].i);
          ctx.fillText(lbl, Math.max(padL, tx-6), H-12);
        }
      }
    }

    function draw(){
      if (!canvas) return;
      const series = computeSeries(selectedTarget);
      if (!series.ys.length){
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0,0,canvas.width,canvas.height);
        ctx.fillStyle='rgba(255,255,255,.65)';
        ctx.font='14px system-ui, -apple-system, Segoe UI, Roboto, Arial';
        ctx.textAlign='center';
        ctx.fillText('No data yet for this target.', canvas.width/2, canvas.height/2);
        return;
      }
      // draw expects the per-game point series array [{i,v}, ...]
      drawChart(series.ys);
    }

    renderButtons();
    draw();
  };;
})();
